for p,v in remote['native-layer-probe']['files'].items():
 if p in old:assert v['sha256']==old[p]['sha256'],p
f=BASE/'full-model-readiness'
for p,v in remote['full-model-readiness']['files'].items():assert row(f/p,f)['sha256']==v['sha256'],p
# Original successful runtime/source/JIT payloads, including the retained remote cache.
raw=[row(p,b) for p in sorted(b.rglob('*')) if p.is_file() and (str(p.relative_to(b)).startswith(('attempt-05/','jit-preflight/','jit-mhc-preflight/','sources/')) or p.name in ['jit-preflight.log','jit-mhc-preflight.log','jit_preflight.py','jit_mhc_preflight.py','source-hashes.json','postflight.txt'])]
save(b/'raw-transfer-manifest.json',raw)
s=(b/'README.md').read_text().replace('[13个最终运行原始文件传输清单]',f'[{len(raw)}个成功运行与预检原始文件传输清单]')
(b/'README.md').write_text(s)
with (b/'analyze.log').open('w') as out:subprocess.run(['python3','-B',str(b/'analyze.py')],stdout=out,check=True)
save(f/'raw-transfer-manifest.json',[row(p,f) for p in sorted(f.rglob('*')) if p.is_file() and (p.name=='probe.py' or 'results' in p.parts)])
for name in remote:
 d=BASE/name
 save(d/'manifest.json',dict(scope='Final successful evidence only; no full-model or quality pass',files=[row(p,d) for p in sorted(d.rglob('*')) if p.is_file() and p.name"'!='"'manifest.json']))
# The remote operation rechecks exact path and every pre-inspected file SHA before mutation.
payload={}
for name,v in remote.items():
 d=BASE/name
 deletes=['results','run.py','launch.py','run.log','attempt-02','attempt-03','attempt-04','cache','tmp'] if name=='native-layer-probe' else ['probe-attempt01.py','first-failure.txt']
 uploads={}
 for p in d.rglob('*'):
  if p.is_file():
   rel=str(p.relative_to(d));sha=hashlib.sha256(p.read_bytes()).hexdigest()
   if rel not in v['files'] or v['files'][rel]['sha256']"'!=sha:uploads[rel]=base64.b64encode(p.read_bytes()).decode()
 payload[name]=dict(path=v['"'path'],before=v['files'],links=v['links'],deletes=deletes,uploads=uploads)
