import json,hashlib,base64,shutil,os
payload=PAYLOAD
for name,v in payload.items():
 b=Path(v['path'])
 assert str(b)=='/home/ubuntu/ai-infra-book-experiments/ch02/02-05/'+name and b.resolve()==b and b.is_dir()
 for rel,r in v['before'].items():
  p=b/rel
  assert not p.is_symlink() and p.is_file() and hashlib.sha256(p.read_bytes()).hexdigest()==r['sha256'],rel
 for rel,target in v['links'].items():assert (b/rel).is_symlink() and os.readlink(b/rel)==target
for name,v in payload.items():
