 for rel in v['deletes']:
  p=b/rel
  assert p.parent==b and not p.is_symlink()
  if p.exists():
   if p.is_dir():shutil.rmtree(p)
   else:p.unlink()
   removed.append(rel)
 for rel,data in v['uploads'].items():
  p=b/rel
  assert b in p.resolve().parents and not p.is_symlink()
  p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(data))
 manifest=json.loads((b/'manifest.json').read_text())
 for r in manifest['files']:
  p=b/r['path'];assert p.stat().st_size==r['bytes'] and hashlib.sha256(p.read_bytes()).hexdigest()==r['sha256'],r['path']
 actual={str(p.relative_to(b)) for p in b.rglob('*') if p.is_file() and not p.is_symlink()}
 expected={r['path'] for r in manifest['files']}|{'manifest.json'}
 assert actual==expected, {'extra':sorted(actual-expected),'missing':sorted(expected-actual)}
 print(json.dumps(dict(directory=name,removed=removed,uploaded=len(v['uploads']),manifest_verified=len(manifest['files']),raw_verified=len(json.loads((b/'raw-transfer-manifest.json').read_text())),manifest_sha256=hashlib.sha256((b/'manifest.json').read_bytes()).hexdigest())))
'''.replace('PAYLOAD',repr(payload))
